INSERT INTO di_services ("created_at", "updated_at", "raw_data", "data", "content_hash", "version", "ingestion_run_id", "id") VALUES ($seed$2026-02-16 09:55:35.409473+00$seed$, $seed$2026-02-16 09:55:35.409473$seed$, $seed${"source":"carif-oref","structure_id":"carif-oref--01_GE307361","id":"carif-oref--01_GE2021586","nom":"Ouvrir l'école aux parents pour la réussite des enfants","description":"### Objectif de la formation\n\n- Les formations ont pour but de favoriser l'intégration des parents d'élèves, primo-arrivants, immigrés ou étrangers hors Union européenne, volontaires, en les impliquant notamment dans la scolarité de leur enfant.\n- Attestation de suivi.\n- Validation possible selon le cas (DELF, DCL).\n\n### Contenu de la formation\n\nLes formations portent sur trois axes d'apprentissage :\n- l'acquisition du français (comprendre, parler, lire et écrire) ;\n- la connaissance des valeurs de la République et leur mise en œuvre dans la société française ;\n- la connaissance du fonctionnement et des attentes de l'école vis-à-vis des élèves et des parents.\nCette formation est assurée par des enseignants en Français Langue Seconde, des enseignants des UPE2A, ou des membres d'associations diplômés en FLE-FLS.","lien_source":"https://www.intercariforef.org/formations/formations-intitule-formation/formation-01_GE471359_GE2021586.html","date_maj":"2026-01-14","type":"formation","thematiques":["lecture-ecriture-calcul--maitriser-le-francais"],"frais":null,"frais_precisions":null,"publics":["personnes-exilees"],"publics_precisions":null,"conditions_acces":"Etre primo-arrivants, immigres ou etrangers hors Union europeenne.","commune":"Petite-Rosselle","code_postal":"57540","code_insee":"57537","adresse":"1 Place du Mineur","complement_adresse":null,"longitude":6.850071,"latitude":49.209202,"telephone":"+33387509020","courriel":"ce.0572493A@ac-nancy-metz.fr","modes_accueil":["en-presentiel"],"zone_eligibilite":["08","10","51","52","54","55","57","67","68","88"],"contact