INSERT INTO di_services ("created_at", "updated_at", "raw_data", "data", "content_hash", "version", "ingestion_run_id", "id") VALUES ($seed$2026-02-16 09:55:36.784029+00$seed$, $seed$2026-02-16 09:55:36.784029$seed$, $seed${"source":"carif-oref","structure_id":"carif-oref--07_14262","id":"carif-oref--07_776575S","nom":"FLE : Progresser en français","description":"### Objectif de la formation\n\nLa formation « FRANÇAIS LANGUE ÉTRANGÈRE » vise l'acquisition des bases linguistiques des bénéficiaires pour faciliter le passage à l'écrit dans des situations diverses (écrit volontaire ou obligé). Les personnes sauront comprendre et s'exprimer oralement dans un contexte professionnel et dans des situations diverses et auront acquis ou renforcer les compétences linguistiques attendues en entreprise pour réussir leur projet professionnel par l'accès à l'emploi et/ou à la qualification. Elle doit permettre à tout citoyen allophone de plus de 16 ans et sorti du système scolaire d'évoluer de façon autonome dans les situations les plus diverses et les plus courantes de la vie économique, sociale et professionnelle par le développement de l'ensemble des compétences et connaissances de base. La consolidation des savoirs de base doit permettre une insertion sociale et professionnelle réussie, ancrée dans les réalités culturelles françaises : règles sociales, sociétales françaises et régionales, stéréotypes, relations familiales, monde du travail, monde associatif et le retour et le maintien dans l'emploi, la stabilisation d'un projet professionnel et favoriser si besoin l'accès à une certification et/ou qualification. Développer l'aptitude des personnes à la communication interactive : comprendre, parler, lire et écrire en français dans un contexte social et professionnel.\n\n### Contenu de la formation\n\nElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS1 - Assurer un accueil et une intégration de qualité - 7h - Objectifs : Assurer un accueil et une intégration de qualité S1 : Présenter le centre de formation et ses interlocuteurs - 1h S2 : Identifier le cadre de la formation : Livret d'accueil et Carnet de bord, règlement intérieur, modalités d'organisation, moyens pédagogiques, matériels, Soutien individualisé, Coaching, planning - 4h S3 : Constituer son dossier de rémunération de formation - 1h S4 : Instaurer une dynamique de groupe et de travail - 1h - 7 hElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS2 - Identifier les compétences à acquérir - Positionnement - 7h - Objectif : Identifier les compétences à acquérir et contractualiser les parcours individualisés S1 : Effectuer un positionnement - 1h S2 : Préciser les compétences acquises et définir les compétences à acquérir - 1h S3 : Identifier ses points d'appui, freins et contraintes - 1h S4 : Formaliser les objectifs dans un contrat pédagogique - 1h S5 : Planifier les étapes de progression - 1h S6 : S'approprier son itinéraire individuel de formation - 1h S7 : Appréhender les modalités pédagogiques proposées et les outils mobilisables, dont les plateformes de formation - 1h - 7 hElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS3 - Maîtriser les règles pour une insertion durable : TRE - 11h - Objectif : S'initier aux techniques de recherche d'emploi S1 : Créer son CV par compétences et l'actualiser - 2h S2 : Produire un modèle de lettre de motivation - 2h S3 : Savoir se présenter et argumenter sa candidature - 2h S4 : Utiliser l'emploi store - 2h S5 : Préparer sa visite sur des forums emploi - 2h S6 : Préparer sa visite sur des forums emploi, job dating, café métiers,... - 1h - 11 hElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS4 - Participer à un projet collectif simple, développement des softs skills et transitions - 14h - S1 : Participer à un projet collectif contextualisé au métier S2 : Développer et reconnaître ses soft skills S3 : Se sensibiliser aux transitions numériques et écologiques.","lien_source":"https://www.intercariforef.org/formations/formations-intitule-formation/formation-07_2585152F_776575S.html","date_maj":"2026-01-28","type":"formation","thematiques":["lecture-ecriture-calcul--maitriser-le-francais"],"frais":null,"frais_precisions":null,"publics":["demandeurs-emploi"],"publics_precisions":"Cette formation s adresse a tout public allophone dont l appropriation de la langue francaise est insuffisante pour s inserer en emploi et qui est en recherche d emploi et engage dans une dynamique d insertion ou de reconversion professionn[...]","conditions_acces":"Le dispositif s adresse a toutes les personnes dont l appropriation de la langue francaise est insuffisante pour s inserer dans l emploi.\nAction ouverte a un public age de plus de 16 ans, sorti du systeme scolaire et residant prioritairement en Region Centre-Val de Loire et qui a une reelle motivation pour engager un parcours de formation.","commune":"Blois","code_postal":"41000","code_insee":"41018","adresse":"13 Rue Robert Nau","complement_adresse":null,"longitude":1.332562,"latitude":47.612388,"telephone":"+33243756585","courriel":"via.info@viaformation.fr","modes_accueil":["en-presentiel"],"zone_eligibilite":["18","28","36","37","41","45"],"contact_nom_prenom":null,"lien_mobilisation":null,"modes_mobilisation":["envoyer-un-courriel","telephoner"],"mobilisable_par":["professionnels"],"mobilisation_precisions":null,"volume_horaire_hebdomadaire":null,"nombre_semaines":null,"horaires_accueil":null,"score_qualite":0.8499999999999999,"extra":{"action":{"session":[{"@ref":"182827","@numero":"776575S","periode":{"fin":"20260430","debut":"20260211"},"etat-recrutement":"1","adresse-inscription":{"adresse":{"pays":"FR","ligne":["13 Rue Robert Nau"],"ville":"Blois","codepostal":"41000","departement":"41","denomination":"AFPA de Blois","geolocalisation":{"latitude":"47.612388","longitude":"1.332562"},"code-INSEE-commune":"41018"}},"periode-inscription":{"periode":{"fin":"20260210","debut":"20260115"}},"reference-certification":[null]}],"frais-restants":null,"conventionnement":"1","duree-indicative":"270","info-public-vise":"Cette formation s adresse a tout public allophone dont l appropriation de la langue francaise est insuffisante pour s inserer en emploi et qui est en recherche d emploi et engage dans une dynamique d insertion ou de reconversion professionn[...]","nombre-heures-total":321,"organisme-financeur":[{"extras":[{"@info":"specificites","extra":[{"$":"80006","@ref":"V14","@info":"code-public-vise"},{"$":"Cette formation s'adresse à tout public allophone dont l'appropriation de la langue française est insuffisante pour s'insérer en emploi et qui est en recherche d'emploi et engagé dans une dynamique d'insertion ou de reconversion professionn[...]","@info":"info-public-vise"},{"$":"3","@info":"code-perimetre-recrutement"},{"$":"Programme régional 2025-2028 : Dispositif de formations linguistiques","@info":"programme-financeur"},{"$":"251DF0005A-2-71323","@info":"ref-action-marche-financeur"}]}],"code-financeur":"2","nb-places-financees":10}],"modalites-recrutement":null,"modalites-enseignement":"0","modalites-entrees-sorties":"0"},"formation":{"code-niveau-entree":"1","code-niveau-sortie":"1"}}}$seed$, $seed${"id": "carif-oref--07_776575S", "nom": "FLE : Progresser en français", "type": "formation", "extra": {"action": {"session": [{"@ref": "182827", "@numero": "776575S", "periode": {"fin": "20260430", "debut": "20260211"}, "etat-recrutement": "1", "adresse-inscription": {"adresse": {"pays": "FR", "ligne": ["13 Rue Robert Nau"], "ville": "Blois", "codepostal": "41000", "departement": "41", "denomination": "AFPA de Blois", "geolocalisation": {"latitude": "47.612388", "longitude": "1.332562"}, "code-INSEE-commune": "41018"}}, "periode-inscription": {"periode": {"fin": "20260210", "debut": "20260115"}}, "reference-certification": [null]}], "frais-restants": null, "conventionnement": "1", "duree-indicative": "270", "info-public-vise": "Cette formation s adresse a tout public allophone dont l appropriation de la langue francaise est insuffisante pour s inserer en emploi et qui est en recherche d emploi et engage dans une dynamique d insertion ou de reconversion professionn[...]", "nombre-heures-total": 321, "organisme-financeur": [{"extras": [{"@info": "specificites", "extra": [{"$": "80006", "@ref": "V14", "@info": "code-public-vise"}, {"$": "Cette formation s'adresse à tout public allophone dont l'appropriation de la langue française est insuffisante pour s'insérer en emploi et qui est en recherche d'emploi et engagé dans une dynamique d'insertion ou de reconversion professionn[...]", "@info": "info-public-vise"}, {"$": "3", "@info": "code-perimetre-recrutement"}, {"$": "Programme régional 2025-2028 : Dispositif de formations linguistiques", "@info": "programme-financeur"}, {"$": "251DF0005A-2-71323", "@info": "ref-action-marche-financeur"}]}], "code-financeur": "2", "nb-places-financees": 10}], "modalites-recrutement": null, "modalites-enseignement": "0", "modalites-entrees-sorties": "0"}, "formation": {"code-niveau-entree": "1", "code-niveau-sortie": "1"}}, "frais": null, "source": "carif-oref", "adresse": "13 Rue Robert Nau", "commune": "Blois", "publics": ["demandeurs-emploi"], "courriel": "via.info@viaformation.fr", "date_maj": "2026-01-28", "latitude": 47.612388, "longitude": 1.332562, "telephone": "+33243756585", "code_insee": "41018", "code_postal": "41000", "description": "### Objectif de la formation\n\nLa formation « FRANÇAIS LANGUE ÉTRANGÈRE » vise l'acquisition des bases linguistiques des bénéficiaires pour faciliter le passage à l'écrit dans des situations diverses (écrit volontaire ou obligé). Les personnes sauront comprendre et s'exprimer oralement dans un contexte professionnel et dans des situations diverses et auront acquis ou renforcer les compétences linguistiques attendues en entreprise pour réussir leur projet professionnel par l'accès à l'emploi et/ou à la qualification. Elle doit permettre à tout citoyen allophone de plus de 16 ans et sorti du système scolaire d'évoluer de façon autonome dans les situations les plus diverses et les plus courantes de la vie économique, sociale et professionnelle par le développement de l'ensemble des compétences et connaissances de base. La consolidation des savoirs de base doit permettre une insertion sociale et professionnelle réussie, ancrée dans les réalités culturelles françaises : règles sociales, sociétales françaises et régionales, stéréotypes, relations familiales, monde du travail, monde associatif et le retour et le maintien dans l'emploi, la stabilisation d'un projet professionnel et favoriser si besoin l'accès à une certification et/ou qualification. Développer l'aptitude des personnes à la communication interactive : comprendre, parler, lire et écrire en français dans un contexte social et professionnel.\n\n### Contenu de la formation\n\nElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS1 - Assurer un accueil et une intégration de qualité - 7h - Objectifs : Assurer un accueil et une intégration de qualité S1 : Présenter le centre de formation et ses interlocuteurs - 1h S2 : Identifier le cadre de la formation : Livret d'accueil et Carnet de bord, règlement intérieur, modalités d'organisation, moyens pédagogiques, matériels, Soutien individualisé, Coaching, planning - 4h S3 : Constituer son dossier de rémunération de formation - 1h S4 : Instaurer une dynamique de groupe et de travail - 1h - 7 hElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS2 - Identifier les compétences à acquérir - Positionnement - 7h - Objectif : Identifier les compétences à acquérir et contractualiser les parcours individualisés S1 : Effectuer un positionnement - 1h S2 : Préciser les compétences acquises et définir les compétences à acquérir - 1h S3 : Identifier ses points d'appui, freins et contraintes - 1h S4 : Formaliser les objectifs dans un contrat pédagogique - 1h S5 : Planifier les étapes de progression - 1h S6 : S'approprier son itinéraire individuel de formation - 1h S7 : Appréhender les modalités pédagogiques proposées et les outils mobilisables, dont les plateformes de formation - 1h - 7 hElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS3 - Maîtriser les règles pour une insertion durable : TRE - 11h - Objectif : S'initier aux techniques de recherche d'emploi S1 : Créer son CV par compétences et l'actualiser - 2h S2 : Produire un modèle de lettre de motivation - 2h S3 : Savoir se présenter et argumenter sa candidature - 2h S4 : Utiliser l'emploi store - 2h S5 : Préparer sa visite sur des forums emploi - 2h S6 : Préparer sa visite sur des forums emploi, job dating, café métiers,... - 1h - 11 hElément Titre Court : Succès Pack - Accompagnement Vers le Succès - AVS AVS4 - Participer à un projet collectif simple, développement des softs skills et transitions - 14h - S1 : Participer à un projet collectif contextualisé au métier S2 : Développer et reconnaître ses soft skills S3 : Se sensibiliser aux transitions numériques et écologiques.", "lien_source": "https://www.intercariforef.org/formations/formations-intitule-formation/formation-07_2585152F_776575S.html", "thematiques": ["lecture-ecriture-calcul--maitriser-le-francais"], "structure_id": "carif-oref--07_14262", "modes_accueil": ["en-presentiel"], "score_qualite": 0.8499999999999999, "mobilisable_par": ["professionnels"], "nombre_semaines": null, "conditions_acces": "Le dispositif s adresse a toutes les personnes dont l appropriation de la langue francaise est insuffisante pour s inserer dans l emploi.\nAction ouverte a un public age de plus de 16 ans, sorti du systeme scolaire et residant prioritairement en Region Centre-Val de Loire et qui a une reelle motivation pour engager un parcours de formation.", "frais_precisions": null, "horaires_accueil": null, "zone_eligibilite": ["18", "28", "36", "37", "41", "45"], "lien_mobilisation": null, "complement_adresse": null, "contact_nom_prenom": null, "modes_mobilisation": ["envoyer-un-courriel", "telephoner"], "publics_precisions": "Cette formation s adresse a tout public allophone dont l appropriation de la langue francaise est insuffisante pour s inserer en emploi et qui est en recherche d emploi et engage dans une dynamique d insertion ou de reconversion professionn[...]", "mobilisation_precisions": null, "volume_horaire_hebdomadaire": null}$seed$, $seed$8159afe8df73bf98d559d6dea52f3b972d93b137$seed$, 2, $seed$67a53098-3435-4e77-a9c3-8f90a3368d82$seed$, $seed$7158ab99-564c-4457-8ae1-3a19a7aa1d2f$seed$) ON CONFLICT DO NOTHING;
