INSERT INTO di_services ("created_at", "updated_at", "raw_data", "data", "content_hash", "version", "ingestion_run_id", "id") VALUES ($seed$2026-02-16 09:55:38.589798+00$seed$, $seed$2026-02-16 09:55:38.589798$seed$, $seed${"source":"carif-oref","structure_id":"carif-oref--14_OF_0000014841","id":"carif-oref--14_SE_0001611012","nom":"Actions socio-linguistiques complémentaires du CIR (ASL) - Ateliers sociolinguistiques et Compétences Pro","description":"### Objectif de la formation\n\nCe sont des formations de proximité qui visent à rendre autonomes les « apprenants » dans les différents espaces sociaux c'est-à-dire les différents lieux ou institutions de la vie courante (centres sociaux, médiathèque, CAF, CPAM, centre hospitalier, écoles, …).\nL'apprentissage de la langue française est toujours contextualisé dans le respect des valeurs de la République. Les ASL concourent à cette démarche spécifique de développement de programmes destinés à favoriser l'intégration sociale, l'accès à l'emploi, l'accès aux droits, l'accès à la culture…\n1. Permettre l'autonomie linguistique des primo-arrivants par l'apprentissage du français jusqu'au niveau A2\n2. Favoriser l'insertion professionnelle par l'acquisition de compétences linguistiques à visée professionnelle\n3. Lutter contre l'isolement et favoriser la prise ou la reprise de confiance en soi\n4. Développer l'accessibilité aux droits notamment par l'apprentissage du numérique\n5. Impliquer les participants dans la vie du centre et dans la vie locale pour faciliter le développement d'une citoyenneté active\n\n### Contenu de la formation\n\nNotre projet s'inscrit dans l'axe de l'apprentissage linguistique mais avec une dimension civique intégrée qui en fait sa spécificité.\nNotre approche d'apprentissage :\nChaque module de notre programme raconte une histoire : celle d'hommes et de femmes qui, partis de leur pays d'origine avec leurs rêves et leurs compétences, construisent pas à pas leur nouvelle vie en France. Le français devient alors non pas une matière scolaire, mais l'outil de leur émancipation, le moyen de faire entendre leur voix, de défendre leurs droits, d'accompagner leurs enfants dans leur scolarité… d'élaborer un avenir.\nContenu plus étayé et plu personnalisé pour répondre aux nouvelles exigences du passage a terme du niveau A2 obligatoire et de l'examen civique.","lien_source":"https://www.intercariforef.org/formations/formations-intitule-formation/formation-14_AF_0000242984_SE_0001611012.html","date_maj":"2025-12-09","type":"formation","thematiques":["lecture-ecriture-calcul--maitriser-le-francais"],"frais":null,"frais_precisions":null,"publics":["personnes-exilees"],"publics_precisions":null,"conditions_acces":"Aucun","commune":"Pontault-Combault","code_postal":"77340","code_insee":"77373","adresse":"3 Rue de l'Orme au Charron","complement_adresse":null,"longitude":2.609679,"latitude":48.800217,"telephone":"+33160285101","courriel":"cscpontault@gmail.com","modes_accueil":["en-presentiel"],"zone_eligibilite":["75","77","78","91","92","93","94","95"],"contact_nom_prenom":null,"lien_mobilisation":null,"modes_mobilisation":["envoyer-un-courriel","telephoner"],"mobilisable_par":["professionnels"],"mobilisation_precisions":null,"volume_horaire_hebdomadaire":4,"nombre_semaines":null,"horaires_accueil":null,"score_qualite":0.9000000000000001,"extra":{"action":{"session":[{"@ref":"282093","@numero":"SE_0001611012","periode":{"fin":"20260626","debut":"20250929"},"contact-session":[{"@tag":"principal","coordonnees":{"nom":"Contact","prenom":"Centre social et culturel","telfixe":{"numtel":["0160285101"]},"courriel":"cscpontault@gmail.com"},"type-contact":"0"}],"etat-recrutement":"1","adresse-inscription":{"adresse":{"pays":"FR","ligne":["Centre social et culturel","3 Rue de l Orme au Charron"],"ville":"Pontault-Combault","codepostal":"77340","departement":"77","denomination":"Centre social et culturel","geolocalisation":{"latitude":"48.800217","longitude":"2.609679"},"code-INSEE-commune":"77373"}},"reference-certification":[null]}],"frais-restants":null,"conventionnement":"1","duree-indicative":null,"info-public-vise":null,"nombre-heures-total":120,"organisme-financeur":[{"extras":[{"@info":"specificites","extra":[{"$":"81023","@ref":"V14","@info":"code-public-vise"},{"$":"81042","@ref":"V14","@info":"code-public-vise"},{"$":"3","@info":"code-perimetre-recrutement"},{"$":"Actions socio-linguistiques (ASL) complémentaires du CIR 77 - 2025-2026","@info":"programme-financeur"}]}],"code-financeur":"19"}],"modalites-recrutement":null,"modalites-enseignement":"0","modalites-entrees-sorties":"1"},"formation":{"code-niveau-entree":"1","code-niveau-sortie":"1"}}}$seed$, $seed${"id": "carif-oref--14_SE_0001611012", "nom": "Actions socio-linguistiques complémentaires du CIR (ASL) - Ateliers sociolinguistiques et Compétences Pro", "type": "formation", "extra": {"action": {"session": [{"@ref": "282093", "@numero": "SE_0001611012", "periode": {"fin": "20260626", "debut": "20250929"}, "contact-session": [{"@tag": "principal", "coordonnees": {"nom": "Contact", "prenom": "Centre social et culturel", "telfixe": {"numtel": ["0160285101"]}, "courriel": "cscpontault@gmail.com"}, "type-contact": "0"}], "etat-recrutement": "1", "adresse-inscription": {"adresse": {"pays": "FR", "ligne": ["Centre social et culturel", "3 Rue de l Orme au Charron"], "ville": "Pontault-Combault", "codepostal": "77340", "departement": "77", "denomination": "Centre social et culturel", "geolocalisation": {"latitude": "48.800217", "longitude": "2.609679"}, "code-INSEE-commune": "77373"}}, "reference-certification": [null]}], "frais-restants": null, "conventionnement": "1", "duree-indicative": null, "info-public-vise": null, "nombre-heures-total": 120, "organisme-financeur": [{"extras": [{"@info": "specificites", "extra": [{"$": "81023", "@ref": "V14", "@info": "code-public-vise"}, {"$": "81042", "@ref": "V14", "@info": "code-public-vise"}, {"$": "3", "@info": "code-perimetre-recrutement"}, {"$": "Actions socio-linguistiques (ASL) complémentaires du CIR 77 - 2025-2026", "@info": "programme-financeur"}]}], "code-financeur": "19"}], "modalites-recrutement": null, "modalites-enseignement": "0", "modalites-entrees-sorties": "1"}, "formation": {"code-niveau-entree": "1", "code-niveau-sortie": "1"}}, "frais": null, "source": "carif-oref", "adresse": "3 Rue de l'Orme au Charron", "commune": "Pontault-Combault", "publics": ["personnes-exilees"], "courriel": "cscpontault@gmail.com", "date_maj": "2025-12-09", "latitude": 48.800217, "longitude": 2.609679, "telephone": "+33160285101", "code_insee": "77373", "code_postal": "77340", "description": "### Objectif de la formation\n\nCe sont des formations de proximité qui visent à rendre autonomes les « apprenants » dans les différents espaces sociaux c'est-à-dire les différents lieux ou institutions de la vie courante (centres sociaux, médiathèque, CAF, CPAM, centre hospitalier, écoles, …).\nL'apprentissage de la langue française est toujours contextualisé dans le respect des valeurs de la République. Les ASL concourent à cette démarche spécifique de développement de programmes destinés à favoriser l'intégration sociale, l'accès à l'emploi, l'accès aux droits, l'accès à la culture…\n1. Permettre l'autonomie linguistique des primo-arrivants par l'apprentissage du français jusqu'au niveau A2\n2. Favoriser l'insertion professionnelle par l'acquisition de compétences linguistiques à visée professionnelle\n3. Lutter contre l'isolement et favoriser la prise ou la reprise de confiance en soi\n4. Développer l'accessibilité aux droits notamment par l'apprentissage du numérique\n5. Impliquer les participants dans la vie du centre et dans la vie locale pour faciliter le développement d'une citoyenneté active\n\n### Contenu de la formation\n\nNotre projet s'inscrit dans l'axe de l'apprentissage linguistique mais avec une dimension civique intégrée qui en fait sa spécificité.\nNotre approche d'apprentissage :\nChaque module de notre programme raconte une histoire : celle d'hommes et de femmes qui, partis de leur pays d'origine avec leurs rêves et leurs compétences, construisent pas à pas leur nouvelle vie en France. Le français devient alors non pas une matière scolaire, mais l'outil de leur émancipation, le moyen de faire entendre leur voix, de défendre leurs droits, d'accompagner leurs enfants dans leur scolarité… d'élaborer un avenir.\nContenu plus étayé et plu personnalisé pour répondre aux nouvelles exigences du passage a terme du niveau A2 obligatoire et de l'examen civique.", "lien_source": "https://www.intercariforef.org/formations/formations-intitule-formation/formation-14_AF_0000242984_SE_0001611012.html", "thematiques": ["lecture-ecriture-calcul--maitriser-le-francais"], "structure_id": "carif-oref--14_OF_0000014841", "modes_accueil": ["en-presentiel"], "score_qualite": 0.9000000000000001, "mobilisable_par": ["professionnels"], "nombre_semaines": null, "conditions_acces": "Aucun", "frais_precisions": null, "horaires_accueil": null, "zone_eligibilite": ["75", "77", "78", "91", "92", "93", "94", "95"], "lien_mobilisation": null, "complement_adresse": null, "contact_nom_prenom": null, "modes_mobilisation": ["envoyer-un-courriel", "telephoner"], "publics_precisions": null, "mobilisation_precisions": null, "volume_horaire_hebdomadaire": 4}$seed$, $seed$526cdc66a4854855a0d86427a63ff2ccf6117849$seed$, 2, $seed$67a53098-3435-4e77-a9c3-8f90a3368d82$seed$, $seed$6155cec5-09cb-4fa9-8e4b-e3973052afff$seed$) ON CONFLICT DO NOTHING;
INSERT INTO di_services ("created_at", "updated_at", "raw_data", "data", "content_hash", "version", "ingestion_run_id", "id") VALUES ($seed$2026-02-16 09:55:38.589798+00$seed$, $seed$2026-02-16 09:55:38.589798$seed$, $seed${"source":"carif-oref","structure_id":"carif-oref--14_OF_0000012792","id":"carif-oref--14_SE_0001597312","nom":"Actions socio-linguistiques complémentaires du CIR (ASL) - Ateliers linguistiques du soir","description":"### Objectif de la formation\n\nAccéder à l'emploi ou préparer une réorientation professionnelle\nUtiliser l'informatique\nPréparer un diplôme ou une certification de langue française [DILF, DELF A1, DELF A2 ou DELF B1 selon le niveau du bénéficiaire]\nDevenir autonome au quotidien [Apprentissage de la langue française dans ses volets vie pratique / vie publique / vie professionnelle, en vue d'un accès à l'autonomie]\nSe former aux questions civiques et de citoyenneté\nNiveau de langue et de compétences visé par la formation :\nCECRL : A1, A2, B1\n\n### Contenu de la formation\n\nCette action vise l'accompagnement dans l'apprentissage de la langue des salariés et des mères de famille non disponibles en journée. Elle prend en compte les besoins de formation linguistique des demandeurs en vue de lever les freins à l'emploi et à la formation mais aussi acquérir l'autonomie dans ses démarches administratives. Elle permet à chaque demandeur de formation de réaliser un parcours cohérent tenant compte du rythme, de l'individualisation, de son profil et de son projet professionnel. L'apprentissage du français permet de lever un frein à l'emploi et à l'insertion dans la société.\nIl s'agit aussi de permettre aux personnes d'avoir le niveau A2 pour la carte de résidents de 10 ans ou le B1 pour la naturalisation française. Les bénéficiaires sont préparés au TCF, DELF A1, A2 et B1.","lien_source":"https://www.intercariforef.org/formations/formations-intitule-formation/formation-14_AF_0000241678_SE_0001597312.html","date_maj":"2026-01-22","type":"formation","thematiques":["lecture-ecriture-calcul--maitriser-le-francais"],"frais":null,"frais_precisions":null,"publics":["personnes-exilees"],"publics_precisions":"Salaries primo arrivants avec contrat de travail Femmes primo arrivantes ayant des problemes de garde d enfant qui ne leur permettent pas de suivre les cours en journee.","conditions_acces":"Competences linguistiques a l entree en formation :\nCECRL :\nOral : A1.1, A1\nEcrit : A1.1, A1","commune":"Mantes-la-Jolie","code_postal":"78200","code_insee":"78361","adresse":"44 Boulevard Georges Clémenceau","complement_adresse":null,"longitude":1.687963,"latitude":48.99789,"telephone":"+33130946383","courriel":"a.atigui@ifdev.org","modes_accueil":["en-presentiel"],"zone_eligibilite":["75","77","78","91","92","93","94","95"],"contact_nom_prenom":null,"lien_mobilisation":null,"modes_mobilisation":["envoyer-un-courriel","telephoner"],"mobilisable_par":["professionnels"],"mobilisation_precisions":null,"volume_horaire_hebdomadaire":4,"nombre_semaines":null,"horaires_accueil":null,"score_qualite":0.9000000000000001,"extra":{"action":{"session":[{"@ref":"281750","@numero":"SE_0001597312","periode":{"fin":"20261231","debut":"20261105"},"url-session":{"urlweb":["https://ifdevformations.fr/"]},"contact-session":[{"@tag":"principal","coordonnees":{"nom":"Atigui","prenom":"Aicha","courriel":"a.atigui@ifdev.fr"},"type-contact":"0"}],"etat-recrutement":"1","adresse-inscription":{"adresse":{"pays":"FR","ligne":["Ifdev","44 Boulevard Georges Clemenceau"],"ville":"Mantes-la-Jolie","codepostal":"78200","departement":"78","denomination":"Ifdev","geolocalisation":{"latitude":"48.99789","longitude":"1.687963"},"code-INSEE-commune":"78361"}},"periode-inscription":{"periode":{"fin":"20261030","debut":"20260105"}},"reference-certification":[null]}],"frais-restants":null,"conventionnement":"1","duree-indicative":"2 ateliers de 2h chacun","info-public-vise":"Salaries primo arrivants avec contrat de travail Femmes primo arrivantes ayan