e_insee": "93066", "code_postal": "93200", "description": "### Objectif de la formation\n\nDonner à des personnes en difficulté professionnelle en raison de leur méconnaissance de la langue française la possibilité de se familiariser avec le langage professionnel et spécifique au monde du travail en France.\n\n### Contenu de la formation\n\nLa formation sera articulée autour des trois modules :\nCompétences linguistiques de base (Oral / Ecrit), FOS (visée professionnel et sociale), citoyenneté, etc.\nTechniques de Recherche d'Emploi : CV, lettre de motivation, recherche d'emploi / formation, monde de l'entreprise, marché du travail, etc.\nModule informatique et internet: recherche d'emploi, outils numériques, monde contemporain, ressources du territoire, mobilité, etc.\nElle est complétée par un suivi individualisé et un accompagnement à l'emploi.", "lien_source": "https://www.intercariforef.org/formations/formations-intitule-formation/formation-14_AF_0000242613_SE_0001608026.html", "thematiques": ["lecture-ecriture-calcul--maitriser-le-francais"], "structure_id": "carif-oref--14_OF_0000005723", "modes_accueil": ["en-presentiel"], "score_qualite": 0.9000000000000001, "mobilisable_par": ["professionnels"], "nombre_semaines": null, "conditions_acces": "Competences linguistiques a l entree en formation :\nCECRL :\nOral : A1.1\nEcrit : A1.1", "frais_precisions": null, "horaires_accueil": null, "zone_eligibilite": ["75", "77", "78", "91", "92", "93", "94", "95"], "lien_mobilisation": null, "complement_adresse": null, "contact_nom_prenom": null, "modes_mobilisation": ["envoyer-un-courriel", "telephoner"], "publics_precisions": "+ demandeurs d asile", "mobilisation_precisions": null, "volume_horaire_hebdomadaire": null}$seed$, $seed$046baa7c7070d64ddbe0c4973f78f55a7bb65ea5$seed$, 2, $seed$67a53098-3435-4e77-a9c3-8f90a3368d82$seed$, $seed$87396d48-2f19-489d-b31d-ce0b6dfa5e89$seed$) ON CONFLICT DO NOTHING;
INSERT INTO di_services ("created_at", "updated_at", "raw_data", "data", "content_hash", "version", "ingestion_run_id", "id") VALUES ($seed$2026-02-16 11:10:17.34045+00$seed$, $seed$2026-02-16 11:10:17.34045$seed$, $seed${"source":"carif-oref","structure_id":"carif-oref--03_6665","id":"carif-oref--03_2552706S","nom":"Ouvrir l'école aux parents pour la réussite des enfants - OEPRE","description":"### Objectif de la formation\n\nLes formations ont pour but de favoriser l'intégration des parents d'élèves, primo-arrivants, immigrés ou étrangers hors Union européenne, volontaires, en les impliquant notamment dans la scolarité de leur enfant.\n\n### Contenu de la formation\n\nLes formations portent sur trois axes d'apprentissage :\n- l'acquisition du français (comprendre, parler, lire et écrire) ;\n- la connaissance des valeurs de la République et leur mise en œuvre dans la société française ;\n- la connaissance du fonctionnement et des attentes de l'école vis-à-vis des élèves et des parents.\nCette formation est assurée par des enseignants en Français Langue Seconde, des enseignants des UPE2A, ou des membres d'associations diplômés en FLE-FLS","lien_source":"https://www.intercariforef.org/formations/formations-intitule-formation/formation-03_1900311F_2552706S.html","date_maj":"2026-01-06","type":"formation","thematiques":["lecture-ecriture-calcul--maitriser-le-francais"],"frais":null,"frais_precisions":null,"publics":["personnes-exilees","demandeurs-emploi"],"publics_precisions":"Primo-arrivants, refugies sans niveau specifique","conditions_acces":"-","commune":"Bron","code_postal":"69500","code_insee":"69029","adresse":"34 Rue Jean Jaurès","complement_adresse":null,"longitude":4.903545,"latitude":45.730538,"telephone":"+33478268076","courriel":"ce.0693834T@ac-lyon.fr","modes_accueil":["en-presentiel"],"zone_eligibilite":["01","03","07","15","26","38","42","43","63","69","73","74"],"contact_nom_prenom":null,"lien_mobilisation":null,"modes_mobilisation":["telephoner","env